from lib import find_objects, background, is_corner_bar_shape, min_manhattan

def transform(grid):
    bg = background(grid)
    multi, singles = find_objects(grid, bg)
    objs = [{'c': grid[comp[0][0]][comp[0][1]], 'cells': comp} for comp in multi + [[p] for p in singles]]
    key = min((o for o in objs if is_corner_bar_shape(o['cells'])),
              key=lambda o: len(o['cells']))
    groups = {}
    for o in objs:
        if o is not key:
            groups.setdefault(normalize_shape(o['cells'])[1], []).append(o)
    grp = max([v for v in groups.values() if len(v) > 1], key=lambda v: len(v[0]['cells']))
    tgt = max(grp, key=lambda o: min_manhattan(o['cells'], key['cells']))
    out = [row[:] for row in grid]
    for r, c in tgt['cells']:
        out[r][c] = key['c']
    return out

def normalize_shape(cells):
    """A cell set as a canonical tuple-of-tuples 0/1 bounding-box mask with its top-left offset."""
    r0 = min(r for r, c in cells); c0 = min(c for r, c in cells)
    H = max(r for r, c in cells) - r0 + 1; W = max(c for r, c in cells) - c0 + 1
    s = {(r - r0, c - c0) for r, c in cells}
    return (r0, c0), tuple(tuple(1 if (r, c) in s else 0 for c in range(W)) for r in range(H))

